import{_ as a,o,c as e,a2 as d}from"./chunks/framework.DGvnA5EY.js";const r="/workbuddy-guide/assets/01-knowledge.DSZn6ZVr.png",q=JSON.parse('{"title":"第 16 章 收藏不是知识管理，能再次用起来才是","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 收藏 = 安慰自己\\"以后会看\\"，结果再也没打开。真正的知识管理是：存得进，更找得回、 用得上。这一章教你用 WorkBuddy 把收藏变成能复用的资产——核心是\\"存时摘要+打标签， 用时检索，复用产出\\"。","frontmatter":{"title":"第 16 章 收藏不是知识管理，能再次用起来才是"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 16 章 收藏不是知识管理，能再次用起来才是/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 16 章 收藏不是知识管理，能再次用起来才是/index.md","lastUpdated":1791615980000}'),l={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 16 章 收藏不是知识管理，能再次用起来才是/index.md"};function s(n,t,i,h,u,p){return o(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="第-16-章-收藏不是知识管理-能再次用起来才是" tabindex="-1">第 16 章 收藏不是知识管理，能再次用起来才是 <a class="header-anchor" href="#第-16-章-收藏不是知识管理-能再次用起来才是" aria-label="Permalink to &quot;第 16 章 收藏不是知识管理，能再次用起来才是&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）</p></blockquote><p>收藏 = 安慰自己&quot;以后会看&quot;，结果再也没打开。真正的知识管理是：<strong>存得进，更找得回、 用得上</strong>。这一章教你用 WorkBuddy 把收藏变成能复用的资产——核心是&quot;存时摘要+打标签， 用时检索，复用产出&quot;。</p><p><img src="'+r+`" alt="一只小黑把一张张收藏的纸条贴到一面墙上，墙边立着标签和检索框" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;知识管理&quot;，与实际软件界面无关。</em></p><h2 id="一、先想清楚-这次知识管理要交付什么" tabindex="-1">一、先想清楚：这次知识管理要交付什么 <a class="header-anchor" href="#一、先想清楚-这次知识管理要交付什么" aria-label="Permalink to &quot;一、先想清楚：这次知识管理要交付什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>让收藏能&quot;下次用上&quot;</td><td>关于定投的资料，下次能一句话调出</td></tr><tr><td>受众</td><td>谁用</td><td>主要是未来的我自己</td></tr><tr><td>材料</td><td>哪些内容进库</td><td>文章/笔记/截图，非机密</td></tr><tr><td>格式</td><td>库的结构</td><td>每篇：摘要+固定标签+原文链接</td></tr><tr><td>验收</td><td>怎么判断有用</td><td>我能搜到、能基于它产出新东西</td></tr></tbody></table><h2 id="二、先选对-skill-知识管理的组合" tabindex="-1">二、先选对 Skill：知识管理的组合 <a class="header-anchor" href="#二、先选对-skill-知识管理的组合" aria-label="Permalink to &quot;二、先选对 Skill：知识管理的组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式 / Skill</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>资料库类连接器</strong></td><td>跨设备、可协作的知识库</td><td>云端存+检索，适合常协作</td><td>见第一篇第 7 章</td></tr><tr><td><strong>腾讯文档 / kdocs</strong></td><td>在线笔记沉淀</td><td>建&quot;我的知识库&quot;文档树</td><td>需授权</td></tr><tr><td><strong>本地 Markdown / 工作区</strong></td><td>电脑上的笔记文件</td><td>AI 直接读，隐私更稳</td><td>见第一篇第 3 章</td></tr><tr><td><strong>find-skills</strong></td><td>找更专业的知识管理技能</td><td>如&quot;文献管理&quot;&quot;读书笔记&quot;</td><td>零成本入口</td></tr></tbody></table><h2 id="三、真实可复制提示词" tabindex="-1">三、真实可复制提示词 <a class="header-anchor" href="#三、真实可复制提示词" aria-label="Permalink to &quot;三、真实可复制提示词&quot;">​</a></h2><h3 id="提示词-1-存的时候-摘要-打固定标签" tabindex="-1">提示词 1｜存的时候，摘要 + 打固定标签 <a class="header-anchor" href="#提示词-1-存的时候-摘要-打固定标签" aria-label="Permalink to &quot;提示词 1｜存的时候，摘要 + 打固定标签&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这篇文章存进我的知识库，写 3 句摘要，从我的固定标签集合</span></span>
<span class="line"><span>【投资/写作/工具/健康/职场/法律】里选 1–3 个贴上，并记下原文链接和存入日期。</span></span>
<span class="line"><span>不要自创标签。</span></span></code></pre></div><h3 id="提示词-2-用的时候-直接问-我存过什么" tabindex="-1">提示词 2｜用的时候，直接问&quot;我存过什么&quot; <a class="header-anchor" href="#提示词-2-用的时候-直接问-我存过什么" aria-label="Permalink to &quot;提示词 2｜用的时候，直接问&quot;我存过什么&quot;&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我之前存过关于【定投】的资料吗？如果有，把每篇的摘要和原文位置告诉我，</span></span>
<span class="line"><span>并总结这些资料里关于&quot;定投频率&quot;的一致结论和分歧点。</span></span></code></pre></div><h3 id="提示词-3-复用的时候-基于库存产出" tabindex="-1">提示词 3｜复用的时候，基于库存产出 <a class="header-anchor" href="#提示词-3-复用的时候-基于库存产出" aria-label="Permalink to &quot;提示词 3｜复用的时候，基于库存产出&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据我知识库里关于【定投】的内容，帮我写一段发在朋友圈的科普（150 字以内，</span></span>
<span class="line"><span>口语、不劝投、注明&quot;个人整理非建议&quot;），并列出引用的那几篇原文。</span></span></code></pre></div><h2 id="四、执行步骤表" tabindex="-1">四、执行步骤表 <a class="header-anchor" href="#四、执行步骤表" aria-label="Permalink to &quot;四、执行步骤表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>WorkBuddy 做什么</th><th>你要确认什么</th></tr></thead><tbody><tr><td>1</td><td>收到内容，摘要+选固定标签+存库</td><td>标签在你的固定集合内、摘要准确</td></tr><tr><td>2</td><td>你检索&quot;我存过 XX 吗&quot;</td><td>它真能找回、定位准确</td></tr><tr><td>3</td><td>基于库存产出新内容</td><td>引用了真实存过的原文</td></tr></tbody></table><h2 id="五、两种-仓库-怎么选" tabindex="-1">五、两种&quot;仓库&quot;怎么选 <a class="header-anchor" href="#五、两种-仓库-怎么选" aria-label="Permalink to &quot;五、两种&quot;仓库&quot;怎么选&quot;">​</a></h2><ul><li><strong>本地笔记/文件</strong>：你电脑上的 Markdown、文档，AI 能直接读（配合工作区，见第一篇第 3 章），隐私更稳</li><li><strong>云端知识库</strong>：跨设备、可协作（资料库类连接器，见第一篇第 7 章）</li></ul><p>怕丢就本地+云端双份；常协作就云端为主。</p><h2 id="六、零成本-skill-把-收藏即摘要-固化" tabindex="-1">六、零成本 Skill：把&quot;收藏即摘要&quot;固化 <a class="header-anchor" href="#六、零成本-skill-把-收藏即摘要-固化" aria-label="Permalink to &quot;六、零成本 Skill：把&quot;收藏即摘要&quot;固化&quot;">​</a></h2><p>跑顺提示词 1 后，用 <code>skill-creator</code> 固化成&quot;存入即摘要&quot;技能：以后任何新链接/文章 丢给它，自动按你的固定标签集摘要入库，不用每次写长提示词。</p><h2 id="七、实际效果与验收标准" tabindex="-1">七、实际效果与验收标准 <a class="header-anchor" href="#七、实际效果与验收标准" aria-label="Permalink to &quot;七、实际效果与验收标准&quot;">​</a></h2><p><strong>实际效果</strong>：你的收藏从&quot;死库存&quot;变成&quot;活资产&quot;——能搜到、能复用。</p><p><strong>验收标准</strong>：</p><ul><li>[ ] 存的内容都有摘要 + 固定标签 + 原文位置</li><li>[ ] 检索&quot;我存过 XX 吗&quot;能准确找回</li><li>[ ] 标签严格在你的固定集合内（没冒出搜不到的词）</li></ul><h2 id="八、一个必须记住的坑" tabindex="-1">八、一个必须记住的坑 <a class="header-anchor" href="#八、一个必须记住的坑" aria-label="Permalink to &quot;八、一个必须记住的坑&quot;">​</a></h2><p><strong>标签要你定，别全扔给 AI 自由发挥</strong>。否则它会打出一堆你下次搜不到的词。定 5–10 个 常用固定标签（如 投资/写作/工具/健康），让 AI 在固定集合里选，检索才稳。</p><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>知识库</strong>：集中存放你收集的信息，并能被 AI 检索、引用的&quot;个人图书馆&quot;。</p><p><strong>标签（Tag）</strong>：给内容贴的归类词，是以后能快速找回的关键。固定集合比自由发挥可靠。</p><p><strong>复用</strong>：不是&quot;再看一遍&quot;，而是把旧内容当素材，让 AI 产出新东西。</p><p><strong>零成本 Skill</strong>：用 skill-creator 把&quot;存入即摘要&quot;固化成专属技能。</p></blockquote><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 挑 3 篇你收藏过没看的文章，让 AI 摘要+打固定标签存好</li><li>[ ] 试着问它&quot;我存过关于 XX 的吗&quot;，验证能找回</li><li>[ ] 给自己定 5–10 个固定标签词，以后统一用</li><li>[ ] （进阶）用 skill-creator 把&quot;存入即摘要&quot;固化成技能</li></ul><hr><p><em>下一篇：第 17 章——会议结束不是终点，工作才刚刚开始。</em></p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>`,37)])])}const b=a(l,[["render",s]]);export{q as __pageData,b as default};
